import { useState, useEffect, useMemo, useCallback } from 'react';

export interface Note {
  id: string;
  title: string;
  content: string;
  notebookId: string;
  tags: { id: string; name: string }[];
  updatedAt: string;
}

export function useDashboardState(initialNotes: Note[]) {
  const [notes, setNotes] = useState<Note[]>(initialNotes);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedTagId, setSelectedTagId] = useState<string | null>(null);
  const [activeNoteId, setActiveNoteId] = useState<string | null>(initialNotes[0]?.id || null);

  const filteredNotes = useMemo(() => {
    return notes.filter((note) => {
      const matchesSearch =
        note.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        note.content.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesTag =
        selectedTagId === null || note.tags.some((t) => t.id === selectedTagId);
      return matchesSearch && matchesTag;
    });
  }, [notes, searchQuery, selectedTagId]);

  const activeNote = useMemo(() => {
    return notes.find((n) => n.id === activeNoteId) || null;
  }, [notes, activeNoteId]);

  const updateNoteContent = useCallback((content: string) => {
    if (!activeNoteId) return;
    setNotes((prev) =>
      prev.map((n) => (n.id === activeNoteId ? { ...n, content, updatedAt: new Date().toISOString() } : n))
    );
  }, [activeNoteId]);

  return {
    notes,
    filteredNotes,
    activeNote,
    activeNoteId,
    setActiveNoteId,
    searchQuery,
    setSearchQuery,
    selectedTagId,
    setSelectedTagId,
    updateNoteContent,
  };
}
